<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Solicitudes · SIGA</title><style>:root{--ink:#182235;--muted:#667085;--line:#e5e9f1;--brand:#4b42ef;--canvas:#f5f7fb}*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--ink);font-family:Inter,system-ui,sans-serif}.page{max-width:850px;margin:auto;padding:38px 24px}.back{color:var(--brand);font-size:.9rem;text-decoration:none}h1{margin:1rem 0 .35rem;letter-spacing:-.05em}.intro{margin:0 0 28px;color:var(--muted)}.notice{padding:12px 15px;margin-bottom:20px;color:#176b4b;background:#edfbf5;border-radius:9px;font-size:.88rem}.list{display:grid;gap:12px}.form{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:21px;background:#fff;border:1px solid var(--line);border-radius:14px}.form h2{margin:0 0 6px;font-size:1.05rem}.form p{margin:0;color:var(--muted);font-size:.85rem;line-height:1.45}.start{flex:none;padding:.72rem .9rem;color:#fff;background:var(--brand);border-radius:8px;font-size:.85rem;font-weight:750;text-decoration:none}.empty{padding:42px;background:#fff;border:1px dashed #bfc7d7;border-radius:14px;color:var(--muted);text-align:center}@media(max-width:600px){.page{padding:24px 16px}.form{align-items:flex-start;flex-direction:column}}</style></head><body><main class="page"><a class="back" href="{{ route('member.home') }}">← Mi cuenta</a><h1>Solicitudes</h1><p class="intro">Selecciona el tipo de solicitud que necesitas enviar.</p>@if(session('status'))<p class="notice">{{ session('status') }}</p>@endif<div class="list">@forelse($forms as $form)<article class="form"><div><h2>{{ $form->name }}</h2><p>{{ $form->description ?: 'Completa la información requerida para enviar tu solicitud.' }}</p></div><a class="start" href="{{ route('requests.create', $form) }}">Completar</a></article>@empty<div class="empty">No hay formularios disponibles en este momento.</div>@endforelse</div></main></